<?php
$base='../'; $tituloPagina='Mis compras'; require_once __DIR__ . '/../php/conexion.php'; require_once __DIR__ . '/../php/auth.php'; require_once __DIR__ . '/../php/util.php'; requerirInicio(); if(!esCliente()){header('Location: ../admin/panel.php');exit;}
$id=(int)$_SESSION['usuario']['id_usuario'];
$ventas=$conexion->query("SELECT v.id_venta,v.fecha,v.total,v.estado,v.tipo_entrega,v.direccion_entrega,v.fecha_entrega,GROUP_CONCAT(CONCAT(d.cantidad,' x ',p.nombre_producto) SEPARATOR ' · ') productos FROM ventas v JOIN detalle_venta d ON d.id_venta=v.id_venta JOIN productos p ON p.id_producto=d.id_producto WHERE v.id_usuario=$id GROUP BY v.id_venta,v.fecha,v.total,v.estado,v.tipo_entrega,v.direccion_entrega,v.fecha_entrega ORDER BY v.fecha DESC"); require_once __DIR__ . '/../php/encabezado.php';
?><main class="container py-5"><p class="eyebrow">HISTORIAL</p><h1>Mis pedidos</h1><?php mostrarMensaje(); ?><div class="table-responsive mt-4"><table class="table table-hover align-middle"><thead><tr><th>Pedido</th><th>Estado</th><th>Entrega</th><th>Productos</th><th>Total</th></tr></thead><tbody><?php while($v=$ventas->fetch_assoc()): ?><tr><td><strong>#<?php echo $v['id_venta']; ?></strong><br><small><?php echo e($v['fecha']); ?></small></td><td><span class="estado-pedido estado-<?php echo e($v['estado']); ?>"><?php echo e(etiquetaEstadoPedido($v['estado'])); ?></span></td><td><?php echo $v['tipo_entrega'] === 'delivery' ? 'A domicilio' : 'Retiro en tienda'; ?><?php if($v['fecha_entrega']): ?><br><small><?php echo e($v['fecha_entrega']); ?></small><?php endif; ?></td><td><?php echo e($v['productos']); ?></td><td>$<?php echo number_format($v['total'],2); ?></td></tr><?php endwhile; ?></tbody></table></div></main><?php require_once __DIR__ . '/../php/pie.php'; ?>
